c Copyright (C) 2012 Ran Duan (C) 2011-2013 E. Corona, P.G. Martinsson, D. Zorin
c
c This program generates the correction weights 
c
c    D0, D1, D2, D3, D4, D5
c
c from the 2008 Duan Rokhlin JCP paper.
c
c These weights depend only on the parameter h*rk where "h" is mesh distance
c and "rk" is the Helmholtz parameter. (There is als some scaling by powers
c of h.)
c
c The program uses precomputed values on a square in the complex plane,
c and then interpolates to any given value of h*rk.
c
c This program is set up to interface to Matlab via two input and output files.
c The format is in the README.txt file.
c
c The program is modified from a set of functions received from Ran Duan
c in August 2012. Specifically, it incorporates the following functions:
c
c sum_hank.f
c clagreva_new.f
c datalist.f
c prini.f

      PROGRAM main01
      IMPLICIT NONE

      INTEGER ier

      REAL*8 h,real_rk,imag_rk

      COMPLEX*16 ima,hrk,corr0,corr1,corr2,corr3,corr4,corr5,rk
      COMPLEX*16 z,dpment,zs(200),coefs(200),clist0(200),clist1(200)
      COMPLEX*16 clist2(200),clist3(200),clist4(200),clist5(200)

      DATA ima/(0.0d0,1.0d0)/


      OPEN(unit=10,file='indata.txt',status='old')

      READ(10,'(10x,D25.15)') h
      READ(10,'(10x,D25.15)') real_rk
      READ(10,'(10x,D25.15)') imag_rk
      hrk = h*real_rk + ima*h*imag_rk

      CLOSE(10)

      CALL corr_hank(h,hrk,corr0,corr1,corr2,corr3,corr4,corr5,ier)
 
      OPEN(unit=10,file='outdata.txt',status='unknown')

      IF (ier .NE. 0) THEN
        WRITE(*,*) 'ERROR: code ier = ',ier
        STOP
      END IF
     
      WRITE(10,'(a8,I5)')       'ier   = ',ier
      WRITE(10,'(a8,D25.15)')  'h     = ',h
      WRITE(10,'(a8,2D25.15)') 'rk    = ',real_rk,imag_rk
      WRITE(10,'(a8,2D25.15)') 'corr0 = ',real(corr0),imag(corr0)
      WRITE(10,'(a8,2D25.15)') 'corr1 = ',real(corr1),imag(corr1)
      WRITE(10,'(a8,2D25.15)') 'corr2 = ',real(corr2),imag(corr2)
      WRITE(10,'(a8,2D25.15)') 'corr3 = ',real(corr3),imag(corr3)
      WRITE(10,'(a8,2D25.15)') 'corr4 = ',real(corr4),imag(corr4)
      WRITE(10,'(a8,2D25.15)') 'corr5 = ',real(corr5),imag(corr5)

      CLOSE(10)

      END PROGRAM


cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
c
c       THIS IS THE END OF THE DEBUGGING CODE AND THE BEGINING OF
c       THE HANKEL FUNCTION CORRECTION. THE SUBROUTINE HANKEL FUNCTION 
c       CORRECTIONS PRODUCES THE FIRST SIX CORRECTION COEFFICIENTS
c       FOR HANKEL FUNCTION, GIVEN THE USER-SPECIFIED DISCRETIZATION H
c       AND NUMBER OF POINTS PER EACH WAVELENTGH H*RK.
c
cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
c
c
        subroutine corr_hank(h,hrk,corr0,corr1,
     1  corr2,corr3,corr4,corr5,ier)
        implicit real *8(a-h,o-z)
        complex *16 ima,hrk,corr0,corr1,corr2,corr3,corr4,corr5,
     1  z,dpment,zs(200),coefs(200),clist0(200),clist1(200),
     2  clist2(200),clist3(200),clist4(200),clist5(200)
c
        data ima/(0.0d0,1.0d0)/
        save
c
c
c      This subroutine produces the first 6 correction coefficients for 
c      hankel function, given the user specified discretiztion h and the
c      number of points per each wavelength  h*rk. The definition of 
c      correction coefficients are as following:
c
c   corr0=difference between integration and summation for H_0(rk*r) 
c   corr1=difference between integration and summation for H_0(rk*r)*x^2 
c   corr2=difference between integration and summation for H_0(rk*r)*x^4 
c   corr3=difference between integration and summation for H_0(rk*r)*x^2*y^2
c   corr4=difference between integration and summation for H_0(rk*r)*x^6 
c   corr5=difference between integration and summation for H_0(rk*r)*x^4*y^2.
c 
c   All these integrations are on 2-dimensional infinite space.
c 
c                        input parameters:
c  h - the discretiztion step 
c  hrk - h*rk, where rk is the Helmholtz coefficient. hrk should be a
c        complex number which has such property that the larger of its real
c        and imaginery part is between [1.0d-4,1.01d0]
c
c
c                        output parameters:
c  ier - error return code
c      ier=0 means successful execution
c      ier=4 means that hrk is not in the right range of this subroutine
c  corr0,corr1,corr2,corr3,corr4,corr5 - defined as above
c
c
c
c
        mm=200       
        ier=0
        u=hrk
        v=-ima*hrk
c
c       make sure hrk is in the right range of our problem
c
        if((u.ge.0.0d0).and.(v.ge.0.0d0)) goto 1200
        ier=4
        return  
 1200   continue
c
        if(u.ge.v)  rmax=u
        if(u.lt.v)  rmax=v
c
        if((rmax.ge.1.0d-4).and.(rmax.lt.1.01d0)) goto 1400
        ier=4
        return  
 1400   continue
c        
        if((u.ge.v).and.(u.ge.1.0d-4).and.(u.lt.1.0d-3)) izone=7
        if((u.ge.v).and.(u.ge.1.0d-3).and.(u.lt.1.0d-2)) izone=5               
        if((u.ge.v).and.(u.ge.1.0d-2).and.(u.lt.1.0d-1)) izone=3               
        if((u.ge.v).and.(u.ge.1.0d-1).and.(u.lt.1.01d0)) izone=1               
c
        if((u.lt.v).and.(v.ge.1.0d-4).and.(v.lt.1.0d-3)) izone=8
        if((u.lt.v).and.(v.ge.1.0d-3).and.(v.lt.1.0d-2)) izone=6               
        if((u.lt.v).and.(v.ge.1.0d-2).and.(v.lt.1.0d-1)) izone=4               
        if((u.lt.v).and.(v.ge.1.0d-1).and.(v.lt.1.01d0)) izone=2
c
        call prinf('izone=*',izone,1)
c
c       zone:7
c

        if(izone.eq.7) then
c
          dpment=1.0d-4
          ction=2.0d3
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1007(clist0)
        call data_clist1107(clist1)
        call data_clist1207(clist2)
        call data_clist1307(clist3)
        call data_clist1407(clist4)
        call data_clist1507(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*(h*1.0d3)**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*(h*1.0d3)**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*(h*1.0d3)**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*(h*1.0d3)**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*1.0d3)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*(h*1.0d3)**8
c
        endif
c
c
c       zone:5
c

        if(izone.eq.5) then
c
          dpment=1.0d-3
          ction=2.0d2
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1005(clist0)
        call data_clist1105(clist1)
        call data_clist1205(clist2)
        call data_clist1305(clist3)
        call data_clist1405(clist4)
        call data_clist1505(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*(h*1.0d2)**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*(h*1.0d2)**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*(h*1.0d2)**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*(h*1.0d2)**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*1.0d2)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*(h*1.0d2)**8
c
        endif
c
c       zone:3
c
        if(izone.eq.3) then
c
          dpment=1.0d-2
          ction=2.0d1
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1003(clist0)
        call data_clist1103(clist1)
        call data_clist1203(clist2)
        call data_clist1303(clist3)
        call data_clist1403(clist4)
        call data_clist1503(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*(h*1.0d1)**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*(h*1.0d1)**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*(h*1.0d1)**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*(h*1.0d1)**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*1.0d1)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*(h*1.0d1)**8
c
        endif
c
c
c       zone:1
c
        if(izone.eq.1) then
c
          dpment=1.0d-1
          ction=2.0d0
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1001(clist0)
        call data_clist1101(clist1)
        call data_clist1201(clist2)
        call data_clist1301(clist3)
        call data_clist1401(clist4)
        call data_clist1501(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*h**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*h**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*h**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*h**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*2.0d0)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*h**8
c
        endif
c
c
c
c       zone:8
c

        if(izone.eq.8) then
c
          dpment=1.0d-4*ima
          ction=2.0d3
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1008(clist0)
        call data_clist1108(clist1)
        call data_clist1208(clist2)
        call data_clist1308(clist3)
        call data_clist1408(clist4)
        call data_clist1508(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*(h*1.0d3)**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*(h*1.0d4)**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*(h*1.0d3)**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*(h*1.0d3)**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*1.0d3)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*(h*1.0d3)**8
c
        endif
c
c
c       zone:6
c

        if(izone.eq.6) then
c
          dpment=1.0d-3*ima
          ction=2.0d2
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1006(clist0)
        call data_clist1106(clist1)
        call data_clist1206(clist2)
        call data_clist1306(clist3)
        call data_clist1406(clist4)
        call data_clist1506(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*(h*1.0d2)**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*(h*1.0d3)**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*(h*1.0d2)**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*(h*1.0d2)**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*1.0d2)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*(h*1.0d2)**8
c
        endif               
c
c
c
c       zone:4
c
        if(izone.eq.4) then
c
          dpment=1.0d-2*ima
          ction=2.0d1
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1004(clist0)
        call data_clist1104(clist1)
        call data_clist1204(clist2)
        call data_clist1304(clist3)
        call data_clist1404(clist4)
        call data_clist1504(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*(h*1.0d1)**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*(h*1.0d2)**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*(h*1.0d1)**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*(h*1.0d1)**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*1.0d1)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*(h*1.0d1)**8
c
        endif
cc
c
c
c       zone:2
c
        if(izone.eq.2) then
c
          dpment=1.0d-1*ima
          ction=2.0d0
          z=(hrk-dpment)*ction
c
        call data_zs(zs)
        call data_coefs(coefs)
        call data_clist1002(clist0)
        call data_clist1102(clist1)
        call data_clist1202(clist2)
        call data_clist1302(clist3)
        call data_clist1402(clist4)
        call data_clist1502(clist5)
c
        call clagreva(zs,coefs,mm,z,clist0,corr0)
        corr0=corr0*h**2
c
        call clagreva(zs,coefs,mm,z,clist1,corr1)
        corr1=corr1*(h*1.0d1)**4
c
        call clagreva(zs,coefs,mm,z,clist2,corr2)
        corr2=corr2*h**6
c
        call clagreva(zs,coefs,mm,z,clist3,corr3)
        corr3=corr3*h**6
c
        call clagreva(zs,coefs,mm,z,clist4,corr4)
        corr4=corr4*(h*1.0d1)**8
c
        call clagreva(zs,coefs,mm,z,clist5,corr5)
        corr5=corr5*h**8
c
        endif
c
c
        return 
        end
c
c


cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
c
c    This subroutine contains all the data lists for the interpolation subroutine. 
c    The naming rule is as following: zs is the original square 
c    from 0 to 2+2*i, coefs is the coefficients corresponding to zs produced
c    clagreva.f. list1a0b means the ath order hankel correction on square b. 
c    For example, list1001 means 0th correction on sqaure 1. The number of 
c    square is defined by the following: 1,3,5,7 are along the real axis in 
c    first quadrapole, 2,4,6,8 are along the imaginery axis in the first 
c    quadrapole.
c    1: 0.1-->1.1    3: 0.01-->0.11  5: 0.001-->0.011  7: 0.0001-->0.0011 
c    2: 0.1-->1.1    4: 0.01-->0.11  6: 0.001-->0.011  8: 0.0001-->0.0011.
c 
ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
c
c
c
c
c
        subroutine data_zs(zs)
        implicit real *8 (a-h,o-z)
        dimension zs(400),zs_1(80),zs_2(80),
     1  zs_3(80),zs_4(80),zs_5(80)
c
        data zs_1/
     1     0.10000000000000000000000000000000D+01,
     2     0.00000000000000000000000000000000D+00,
     3     0.94761582192649319686555120601497D+00,
     4     0.28928693203419286101861538694664D-14,
     5     0.89558569139403691508663557462062D+00,
     6     0.10146889196959285474823706982057D-12,
     7     0.84302046116750714421634795131605D+00,
     8     0.92376687883518780570788643281565D-12,
     9     0.79207399574324262897827439862827D+00,
     *     0.45708957441494691267547487078492D-11,
     1     0.73993559990539661669192780936156D+00,
     2     0.17398585612921581835042712865335D-10,
