     4     0.52779871498087624257260029299540D-10,
     5     0.63934036694785621140911160796230D+00,
     6     0.14417177275720904604151364412717D-09,
     7     0.58991457489346179279574666969893D+00,
     8     0.35616321331051497893451339567557D-09,
     9     0.54188104490221132806485533113764D+00,
     *     0.81670903521710614920834186798035D-09,
     1     0.49333617443079305724783685339439D+00,
     2     0.18295288500704185952651122165329D-08,
     3     0.44768028967724697628450831049257D+00,
     4     0.38358764982877069411355807240342D-08,
