     4     0.13302968935060156607721550675359D-06,
     5     0.19791604726695771414129439801854D+00,
     6     0.27282086183240657385430462373955D-06,
     7     0.16244166777950265793097176550041D+00,
     8     0.57005673304246221850064911054386D-06,
