c 
c 
c 
c 
c 
        subroutine clagrini(t,n,coefs)
        implicit real *8 (a-h,o-z)
        save
        complex *16 t(1),coefs(1),f(1),cd,
     1      coesum,sum,snear,fun,x
c 
c       this subroutine initializes the lagrange interpolation
c       subroutine in the complex plane. the actual interpolation
c       is performed by the entry clagreva (see below).
c 
c                         input parameters:
c 
c  t - the nodes on which the inetrpolation is based
c  n - the number of elements in array t
c 
c                         output parameters:
c 
c  coefs -  an array of length n to be used by the entry clagreva
c 
c        . . . initialize the interpolation routine based on
c              user-specified nodes t(i)
c 
        done=1
        do 1400 i=1,n
        cd=1
        do 1200 j=1,n
        if(j.eq.i) goto 1200
        cd=cd*(t(i)-t(j))
 1200 continue
        coefs(i)=done/cd
 1400 continue
        call prin2('in clagrini, coefs=*',coefs,n*2)
        return
        end
c 
c 
c 
c 
       subroutine clagreva(t,coefs,n,x,f,fun)
       implicit real *8 (a-h,o-z)
       save
       complex *16 t(1),coefs(1),f(1),cd,
     1      coesum,sum,snear,fun,x
c 
c       this entry interpolates a function f tabulated at the
c       nodes t(i) in the complex plane to obtain  the value of f at
c       the point x.
c 
c                       input parameters:
c 
c  t - the nodes on which the interpolation is based.
c  coefs -  an array of length n produced by the entry clagrini
c  n - the number of elements in array t
c  x - the point in the complex plane where f is to be evaluated
c  f - the values of the function f at the nodes t(i)
c 
c                         output parameters:
c 
c  fun - the inetrpolated value of f at the point x
c 
c       . . . find the node nearest to this point
c 
        knear=1
        cd=x-t(1)
        dd=cd*dconjg(cd)
        dist=dd
        do 2400 i=2,n
        cd=x-t(i)
        dd=cd*dconjg(cd)
        if(dd .gt. dist) goto 2400
        dist=dd
        knear=i
 2400 continue
ccccccc        call prinf('knear=*',knear,1)
c 
c       calculate the coefficient in front of the sum
c 
ccc          call prinf('knear as found is*',knear,1)
        coesum=1
        do 4200 i=1,n
        coesum=coesum*(x-t(i))
 4200 continue
cccccc        call prin2('coesum=*',coesum,2)
c 
c       calculate the sum excluding the term corresponding
c       to knear
c 
        sum=0
        do 4400 i=1,n
        if(i .eq. knear) goto 4400
c 
        sum=sum+coefs(i)*f(i)/(x-t(i))
 4400 continue
        sum=sum*coesum
c 
c       account for the term knear
c 
        snear=1
        do 4600 i=1,n
        if(i .eq. knear) goto 4600
        snear=snear*(x-t(i))
 4600 continue
ccccccc        call prin2('snear=*',snear,2)
c        
        snear=snear*coefs(knear)*f(knear)
cccccc        call prin2('snear=*',snear,2)

c 
        fun=sum+snear
        return
        end

cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

C 
C 
C 
C 
        SUBROUTINE PRINI(IP1,IQ1)
        save
        CHARACTER *1 MES(1), AA(1)
        REAL *4 A(1)
        REAL *8 A2(1)
        REAL *8 A4(1)
        INTEGER *4 IA(1)
        INTEGER *2 IA2(1)
        IP=IP1
        IQ=IQ1
        RETURN
  
C 
C 
C 
C 
C 
        ENTRY PRIN(MES,A,N)
        CALL  MESSPR(MES,IP,IQ)
        IF(IP.NE.0 .AND. N.NE.0) WRITE(IP,1200)(A(J),J=1,N)
        IF(IQ.NE.0 .AND. N.NE.0) WRITE(IQ,1200)(A(J),J=1,N)
 1200 FORMAT(6(2X,E11.5))
         RETURN
C 
C 
C 
C 
        ENTRY PRIN2(MES,A2,N)
        CALL MESSPR(MES,IP,IQ)
        IF(IP.NE.0 .AND. N.NE.0) WRITE(IP,1400)(A2(J),J=1,N)
        IF(IQ.NE.0 .AND. N.NE.0) WRITE(IQ,1400)(A2(J),J=1,N)
 1400 FORMAT(6(2X,E11.5))
        RETURN
C 
C 
C 
C 
        ENTRY PRINQ(MES,A4,N)
        CALL MESSPR(MES,IP,IQ)
        IF(IP.NE.0 .AND. N.NE.0) WRITE(IP,1500)(A4(J),J=1,N)
        IF(IQ.NE.0 .AND. N.NE.0) WRITE(IQ,1500)(A4(J),J=1,N)
 1500 FORMAT(6(2X,e11.5))
        RETURN
C 
C 
C 
C 
        ENTRY PRINF(MES,IA,N)
        CALL MESSPR(MES,IP,IQ)
        IF(IP.NE.0 .AND. N.NE.0) WRITE(IP,1600)(IA(J),J=1,N)
        IF(IQ.NE.0 .AND. N.NE.0) WRITE(IQ,1600)(IA(J),J=1,N)
 1600 FORMAT(10(1X,I7))
        RETURN
C 
C 
C 
C 
        ENTRY PRINF2(MES,IA2,N)
        CALL MESSPR(MES,IP,IQ)
        IF(IP.NE.0 .AND. N.NE.0) WRITE(IP,1600)(IA2(J),J=1,N)
        IF(IQ.NE.0 .AND. N.NE.0) WRITE(IQ,1600)(IA2(J),J=1,N)
        RETURN
C 
C 
C 
C 
        ENTRY PRINA(MES,AA,N)
        CALL MESSPR(MES,IP,IQ)
 2000 FORMAT(1X,80A1)
        IF(IP.NE.0 .AND. N.NE.0) WRITE(IP,2000)(AA(J),J=1,N)
        IF(IQ.NE.0 .AND. N.NE.0) WRITE(IQ,2000)(AA(J),J=1,N)
        RETURN
        END
c 
c 
c 
c 
c 
        SUBROUTINE MESSPR(MES,IP,IQ)
        save
        CHARACTER *1 MES(1),AST
        DATA AST/'*'/
C 
C         DETERMINE THE LENGTH OF THE MESSAGE
C 
        I1=0
        DO 1400 I=1,10000
        IF(MES(I).EQ.AST) GOTO 1600
        I1=I
 1400 CONTINUE
 1600 CONTINUE
         IF ( (I1.NE.0) .AND. (IP.NE.0) )
     1     WRITE(IP,1800) (MES(I),I=1,I1)
         IF ( (I1.NE.0) .AND. (IQ.NE.0) )
     1     WRITE(IQ,1800) (MES(I),I=1,I1)
 1800 FORMAT(1X,80A1)
         RETURN
         END
C 
C 
C 
C 
C 
        SUBROUTINE ZTIME(I)
        save
        J=1
        J=7-I+J
CCCC    I=MRUN(J)
        RETURN
        END
  
